INSERT INTO "public"."round2_challenges" ("id", "difficulty", "title", "description", "scenario", "schema", "base_table_data", "test_cases", "expected_keywords", "total_points", "time_limit", "correct_query", "is_active", "created_at", "updated_at") VALUES (1, 'easy', 'Active Users - Steps Tracker', 'Write a query to find users who walked more than 8000 steps in a day.', 'A fitness app records steps walked by users daily.\nThe company wants to find records where users walked more than 8000 steps.\nThis helps identify active users.\n\nTask: Display user_id and steps where steps > 8000.', 'CREATE TABLE Steps (record_id INT, user_id INT, steps INT);', '[{"rows":[[1,101,9000],[2,102,7000]],"columns":[{"name":"record_id","type":"INT","isForeignKey":false,"isPrimaryKey":true},{"name":"user_id","type":"INT","isForeignKey":false,"isPrimaryKey":false},{"name":"steps","type":"INT","isForeignKey":false,"isPrimaryKey":false}],"tableName":"Steps"}]', '[{"id":1,"name":"Sample Test","points":5,"isHidden":false,"tableData":[{"rows":[[1,101,9000],[2,102,7000]],"columns":[{"name":"record_id","type":"INT","isPrimaryKey":true},{"name":"user_id","type":"INT"},{"name":"steps","type":"INT"}],"tableName":"Steps"}],"description":"Basic test with mixed step counts","expectedOutput":[[101,9000]],"expectedColumns":["user_id","steps"]},{"id":2,"name":"Test Case 2","points":5,"isHidden":false,"tableData":[{"rows":[[1,201,9500],[2,202,6500],[3,203,8200],[4,204,7800]],"columns":[{"name":"record_id","type":"INT","isPrimaryKey":true},{"name":"user_id","type":"INT"},{"name":"steps","type":"INT"}],"tableName":"Steps"}],"description":"Multiple active users","expectedOutput":[[201,9500],[203,8200]],"expectedColumns":["user_id","steps"]},{"id":3,"name":"Test Case 3","points":5,"isHidden":false,"tableData":[{"rows":[[1,301,12000],[2,302,11000],[3,303,7500]],"columns":[{"name":"record_id","type":"INT","isPrimaryKey":true},{"name":"user_id","type":"INT"},{"name":"steps","type":"INT"}],"tableName":"Steps"}],"description":"Users with very high steps","expectedOutput":[[301,12000],[302,11000]],"expectedColumns":["user_id","steps"]},{"id":4,"name":"Test Case 4","points":5,"isHidden":false,"tableData":[{"rows":[[1,401,6000],[2,402,5500]],"columns":[{"name":"record_id","type":"INT","isPrimaryKey":true},{"name":"user_id","type":"INT"},{"name":"steps","type":"INT"}],"tableName":"Steps"}],"description":"All users below threshold","expectedOutput":[],"expectedColumns":["user_id","steps"]},{"id":5,"name":"Hidden Test 1","points":5,"isHidden":true,"tableData":[{"rows":[[1,501,8000],[2,502,8500]],"columns":[{"name":"record_id","type":"INT","isPrimaryKey":true},{"name":"user_id","type":"INT"},{"name":"steps","type":"INT"}],"tableName":"Steps"}],"description":"Edge case - exactly 8000 steps","expectedOutput":[[502,8500]],"expectedColumns":["user_id","steps"]},{"id":6,"name":"Hidden Test 2","points":5,"isHidden":true,"tableData":[{"rows":[[1,601,0],[2,602,7500],[3,603,9200]],"columns":[{"name":"record_id","type":"INT","isPrimaryKey":true},{"name":"user_id","type":"INT"},{"name":"steps","type":"INT"}],"tableName":"Steps"}],"description":"Low and zero steps","expectedOutput":[[603,9200]],"expectedColumns":["user_id","steps"]},{"id":7,"name":"Hidden Test 3","points":5,"isHidden":true,"tableData":[{"rows":[[1,701,15000],[2,702,14900],[3,703,7999]],"columns":[{"name":"record_id","type":"INT","isPrimaryKey":true},{"name":"user_id","type":"INT"},{"name":"steps","type":"INT"}],"tableName":"Steps"}],"description":"Very large step counts","expectedOutput":[[701,15000],[702,14900]],"expectedColumns":["user_id","steps"]},{"id":8,"name":"Hidden Test 4","points":5,"isHidden":true,"tableData":[{"rows":[],"columns":[{"name":"record_id","type":"INT","isPrimaryKey":true},{"name":"user_id","type":"INT"},{"name":"steps","type":"INT"}],"tableName":"Steps"}],"description":"No records in table","expectedOutput":[],"expectedColumns":["user_id","steps"]}]', '["select","from","where"]', 40, 180, 'SELECT user_id, steps FROM Steps WHERE steps > 8000;', true, '2026-03-27 09:37:59.601836+00', '2026-03-27 15:29:29.922+00'), (2, 'easy', 'Active Listeners - Total Songs Played', 'Write a query to find users who have played more than 5 songs in total.', 'A music app tracks songs played by users.\nThey want to identify active listeners who played more than 5 songs total.\n\nTask: Return user_id and total songs played (only for users where total > 5).', 'CREATE TABLE Listening (id INT, user_id INT, songs_played INT);', '[{"rows":[[1,101,3],[2,101,4]],"columns":[{"name":"id","type":"INT","isForeignKey":false,"isPrimaryKey":true},{"name":"user_id","type":"INT","isForeignKey":false,"isPrimaryKey":false},{"name":"songs_played","type":"INT","isForeignKey":false,"isPrimaryKey":false}],"tableName":"Listening"}]', '[{"id":1,"name":"Sample Test","points":5,"isHidden":false,"tableData":[{"rows":[[1,101,3],[2,101,4]],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"user_id","type":"INT"},{"name":"songs_played","type":"INT"}],"tableName":"Listening"}],"description":"Basic grouping with multiple plays by same user","expectedOutput":[[101,7]],"expectedColumns":["user_id","total_songs"]},{"id":2,"name":"Test Case 2","points":5,"isHidden":false,"tableData":[{"rows":[[1,201,2],[2,201,6],[3,202,4],[4,203,8],[5,204,3]],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"user_id","type":"INT"},{"name":"songs_played","type":"INT"}],"tableName":"Listening"}],"description":"Multiple users with different totals","expectedOutput":[[201,8],[203,8]],"expectedColumns":["user_id","total_songs"]},{"id":3,"name":"Test Case 3","points":5,"isHidden":false,"tableData":[{"rows":[[1,301,10],[2,301,15],[3,302,4]],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"user_id","type":"INT"},{"name":"songs_played","type":"INT"}],"tableName":"Listening"}],"description":"One user with many songs","expectedOutput":[[301,25]],"expectedColumns":["user_id","total_songs"]},{"id":4,"name":"Test Case 4","points":5,"isHidden":false,"tableData":[{"rows":[[1,401,3],[2,402,2],[3,403,4]],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"user_id","type":"INT"},{"name":"songs_played","type":"INT"}],"tableName":"Listening"}],"description":"All users below threshold","expectedOutput":[],"expectedColumns":["user_id","total_songs"]},{"id":5,"name":"Hidden Test 1","points":5,"isHidden":true,"tableData":[{"rows":[[1,501,5],[2,502,7]],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"user_id","type":"INT"},{"name":"songs_played","type":"INT"}],"tableName":"Listening"}],"description":"Edge case - exactly 5 songs","expectedOutput":[[502,7]],"expectedColumns":["user_id","total_songs"]},{"id":6,"name":"Hidden Test 2","points":5,"isHidden":true,"tableData":[{"rows":[[1,601,0],[2,602,4],[3,603,9],[4,604,2]],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"user_id","type":"INT"},{"name":"songs_played","type":"INT"}],"tableName":"Listening"}],"description":"Low and zero plays","expectedOutput":[[603,9]],"expectedColumns":["user_id","total_songs"]},{"id":7,"name":"Hidden Test 3","points":5,"isHidden":true,"tableData":[{"rows":[[1,701,25],[2,701,30],[3,702,12]],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"user_id","type":"INT"},{"name":"songs_played","type":"INT"}],"tableName":"Listening"}],"description":"Very high song counts","expectedOutput":[[701,55]],"expectedColumns":["user_id","total_songs"]},{"id":8,"name":"Hidden Test 4","points":5,"isHidden":true,"tableData":[{"rows":[],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"user_id","type":"INT"},{"name":"songs_played","type":"INT"}],"tableName":"Listening"}],"description":"Empty table","expectedOutput":[],"expectedColumns":["user_id","total_songs"]}]', '["select","from","group","having"]', 40, 180, 'SELECT user_id, SUM(songs_played) AS total_songs FROM Listening GROUP BY user_id HAVING SUM(songs_played) > 5;', true, '2026-03-27 09:38:16.757165+00', '2026-03-27 15:18:09.633+00'), (3, 'easy', 'Order Details with Customer Name', 'Join Orders and Customers tables to display order_id and customer_name for matching records.', 'An online store tracks orders and customers separately.\nTo display order details with customer names, both tables are joined.\nOnly matching records should appear.\n\nTask: Return order_id and customer_name.', 'CREATE TABLE Orders (id INT, customer_id INT);\nCREATE TABLE Customers (id INT, name VARCHAR(50));', '[{"rows":[[1,10]],"columns":[{"name":"id","type":"INT","isForeignKey":false,"isPrimaryKey":true},{"name":"customer_id","type":"INT","isForeignKey":false,"isPrimaryKey":false}],"tableName":"Orders"}]', '[{"id":1,"name":"Sample Test","points":5,"isHidden":false,"tableData":[{"rows":[[1,10]],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"customer_id","type":"INT"}],"tableName":"Orders"},{"rows":[[10,"Ram"]],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"name","type":"VARCHAR"}],"tableName":"Customers"}],"description":"Basic JOIN with one matching record","expectedOutput":[[1,"Ram"]],"expectedColumns":["id","name"]},{"id":2,"name":"Test Case 2","points":5,"isHidden":false,"tableData":[{"rows":[[101,201],[102,202],[103,203]],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"customer_id","type":"INT"}],"tableName":"Orders"},{"rows":[[201,"Arjun"],[202,"Priya"],[203,"Karthik"],[204,"Sneha"]],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"name","type":"VARCHAR"}],"tableName":"Customers"}],"description":"Multiple orders and customers","expectedOutput":[[101,"Arjun"],[102,"Priya"],[103,"Karthik"]],"expectedColumns":["id","name"]},{"id":3,"name":"Test Case 3","points":5,"isHidden":false,"tableData":[{"rows":[[301,401],[302,401],[303,402]],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"customer_id","type":"INT"}],"tableName":"Orders"},{"rows":[[401,"Rahul"],[402,"Meena"]],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"name","type":"VARCHAR"}],"tableName":"Customers"}],"description":"Multiple orders per customer","expectedOutput":[[301,"Rahul"],[302,"Rahul"],[303,"Meena"]],"expectedColumns":["id","name"]},{"id":4,"name":"Test Case 4","points":5,"isHidden":false,"tableData":[{"rows":[[501,999]],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"customer_id","type":"INT"}],"tableName":"Orders"},{"rows":[[100,"Vikram"]],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"name","type":"VARCHAR"}],"tableName":"Customers"}],"description":"No matching records","expectedOutput":[],"expectedColumns":["id","name"]},{"id":5,"name":"Hidden Test 1","points":5,"isHidden":true,"tableData":[{"rows":[[601,701]],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"customer_id","type":"INT"}],"tableName":"Orders"},{"rows":[[701,"Suresh"],[702,"Ananya"],[703,"Kiran"]],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"name","type":"VARCHAR"}],"tableName":"Customers"}],"description":"Extra customers without orders","expectedOutput":[[601,"Suresh"]],"expectedColumns":["id","name"]},{"id":6,"name":"Hidden Test 2","points":5,"isHidden":true,"tableData":[{"rows":[[801,901],[802,901],[803,901]],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"customer_id","type":"INT"}],"tableName":"Orders"},{"rows":[[901,"Priyanka"]],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"name","type":"VARCHAR"}],"tableName":"Customers"}],"description":"Multiple orders for same customer","expectedOutput":[[801,"Priyanka"],[802,"Priyanka"],[803,"Priyanka"]],"expectedColumns":["id","name"]},{"id":7,"name":"Hidden Test 3","points":5,"isHidden":true,"tableData":[{"rows":[[1001,1101],[1002,1102],[1003,9999]],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"customer_id","type":"INT"}],"tableName":"Orders"},{"rows":[[1101,"Aditya"],[1102,"Neha"],[1103,"Rohan"]],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"name","type":"VARCHAR"}],"tableName":"Customers"}],"description":"Large dataset with mixed matches","expectedOutput":[[1001,"Aditya"],[1002,"Neha"]],"expectedColumns":["id","name"]},{"id":8,"name":"Hidden Test 4","points":5,"isHidden":true,"tableData":[{"rows":[],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"customer_id","type":"INT"}],"tableName":"Orders"},{"rows":[[1201,"Sneha"]],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"name","type":"VARCHAR"}],"tableName":"Customers"}],"description":"Empty Orders table","expectedOutput":[],"expectedColumns":["id","name"]}]', '["select","from","join"]', 40, 180, 'SELECT o.id, c.name FROM Orders o JOIN Customers c ON o.customer_id = c.id;', true, '2026-03-27 09:38:31.196697+00', '2026-03-27 15:18:15.647+00'), (4, 'easy', 'Above Average Salary', 'Find employees who earn more than the average salary using a subquery.', 'A company stores employee salaries.\nThey want employees earning above average salary.\nThis helps identify high earners.\n\nTask: Return emp_id and salary where salary > average salary.', 'CREATE TABLE Employees (id INT, salary INT);', '[{"rows":[[1,3000],[2,6000]],"columns":[{"name":"id","type":"INT","isForeignKey":false,"isPrimaryKey":true},{"name":"salary","type":"INT","isForeignKey":false,"isPrimaryKey":false}],"tableName":"Employees"}]', '[{"id":1,"name":"Sample Test","points":5,"isHidden":false,"tableData":[{"rows":[[1,3000],[2,6000]],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"salary","type":"INT"}],"tableName":"Employees"}],"description":"Basic subquery with two employees","expectedOutput":[[2,6000]],"expectedColumns":["id","salary"]},{"id":2,"name":"Test Case 2","points":5,"isHidden":false,"tableData":[{"rows":[[101,45000],[102,52000],[103,38000],[104,61000],[105,48000]],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"salary","type":"INT"}],"tableName":"Employees"}],"description":"Multiple employees with varying salaries","expectedOutput":[[102,52000],[104,61000]],"expectedColumns":["id","salary"]},{"id":3,"name":"Test Case 3","points":5,"isHidden":false,"tableData":[{"rows":[[201,60000],[202,65000],[203,70000],[204,55000],[205,72000]],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"salary","type":"INT"}],"tableName":"Employees"}],"description":"High average with many employees","expectedOutput":[[203,70000],[205,72000]],"expectedColumns":["id","salary"]},{"id":4,"name":"Test Case 4","points":5,"isHidden":false,"tableData":[{"rows":[[301,50000],[302,50000],[303,50000]],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"salary","type":"INT"}],"tableName":"Employees"}],"description":"All employees have same salary","expectedOutput":[],"expectedColumns":["id","salary"]},{"id":5,"name":"Hidden Test 1","points":5,"isHidden":true,"tableData":[{"rows":[[401,25000],[402,28000],[403,90000],[404,26000]],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"salary","type":"INT"}],"tableName":"Employees"}],"description":"One high outlier","expectedOutput":[[403,90000]],"expectedColumns":["id","salary"]},{"id":6,"name":"Hidden Test 2","points":5,"isHidden":true,"tableData":[{"rows":[[501,-5000],[502,0],[503,10000],[504,5000]],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"salary","type":"INT"}],"tableName":"Employees"}],"description":"Negative and zero salaries","expectedOutput":[[503,10000]],"expectedColumns":["id","salary"]},{"id":7,"name":"Hidden Test 3","points":5,"isHidden":true,"tableData":[{"rows":[[601,45000],[602,46000],[603,47000],[604,48000],[605,55000],[606,42000]],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"salary","type":"INT"}],"tableName":"Employees"}],"description":"Large number of employees","expectedOutput":[[605,55000]],"expectedColumns":["id","salary"]},{"id":8,"name":"Hidden Test 4","points":5,"isHidden":true,"tableData":[{"rows":[],"columns":[{"name":"id","type":"INT","isPrimaryKey":true},{"name":"salary","type":"INT"}],"tableName":"Employees"}],"description":"Empty table","expectedOutput":[],"expectedColumns":["id","salary"]}]', '["select","from","where","from"]', 40, 180, 'SELECT id, salary FROM Employees WHERE salary > (SELECT AVG(salary) FROM Employees);', true, '2026-03-27 09:38:47.661377+00', '2026-03-27 15:18:30.351+00'), (5, 'medium', 'Premium Customers - Completed Orders', 'Find customers whose total spending on Completed orders exceeds ₹3000.', 'An online store tracks customers and their orders in separate tables.\nOnly orders marked as ''Completed'' should be considered for spending analysis.\nThe company wants to find customers whose total completed spending exceeds ₹3000.\n\nTask: Return customer_name and total_spent.', 'CREATE TABLE Customers (customer_id INT, name VARCHAR(50));\nCREATE TABLE Orders (order_id INT, customer_id INT, amount INT, status VARCHAR(20));', '[{"rows":[[1,"Arun"],[2,"Meena"]],"columns":[{"name":"customer_id","type":"INT","isForeignKey":false,"isPrimaryKey":true},{"name":"name","type":"VARCHAR","isForeignKey":false,"isPrimaryKey":false}],"tableName":"Customers"}]', '[{"id":1,"name":"Sample Test","points":10,"isHidden":false,"tableData":[{"rows":[[1,"Arun"],[2,"Meena"]],"columns":[{"name":"customer_id","type":"INT","isPrimaryKey":true},{"name":"name","type":"VARCHAR"}],"tableName":"Customers"},{"rows":[[1,1,2000,"Completed"],[2,1,1500,"Completed"],[3,2,5000,"Pending"]],"columns":[{"name":"order_id","type":"INT","isPrimaryKey":true},{"name":"customer_id","type":"INT"},{"name":"amount","type":"INT"},{"name":"status","type":"VARCHAR"}],"tableName":"Orders"}],"description":"Mixed completed and pending orders","expectedOutput":[["Arun",3500]],"expectedColumns":["name","total_spent"]},{"id":2,"name":"Test Case 2","points":10,"isHidden":false,"tableData":[{"rows":[[101,"Rahul"],[102,"Priya"],[103,"Karthik"]],"columns":[{"name":"customer_id","type":"INT","isPrimaryKey":true},{"name":"name","type":"VARCHAR"}],"tableName":"Customers"},{"rows":[[1,101,2500,"Completed"],[2,101,1800,"Completed"],[3,102,4000,"Completed"],[4,103,1200,"Pending"],[5,102,1000,"Completed"]],"columns":[{"name":"order_id","type":"INT","isPrimaryKey":true},{"name":"customer_id","type":"INT"},{"name":"amount","type":"INT"},{"name":"status","type":"VARCHAR"}],"tableName":"Orders"}],"description":"Multiple customers with completed orders","expectedOutput":[["Rahul",4300],["Priya",5000]],"expectedColumns":["name","total_spent"]},{"id":3,"name":"Test Case 3","points":10,"isHidden":false,"tableData":[{"rows":[[201,"Sneha"],[202,"Vikram"]],"columns":[{"name":"customer_id","type":"INT","isPrimaryKey":true},{"name":"name","type":"VARCHAR"}],"tableName":"Customers"},{"rows":[[1,201,1500,"Completed"],[2,201,1500,"Completed"],[3,202,3000,"Completed"]],"columns":[{"name":"order_id","type":"INT","isPrimaryKey":true},{"name":"customer_id","type":"INT"},{"name":"amount","type":"INT"},{"name":"status","type":"VARCHAR"}],"tableName":"Orders"}],"description":"Boundary case - exactly 3000","expectedOutput":[["Sneha",3000]],"expectedColumns":["name","total_spent"]},{"id":4,"name":"Test Case 4","points":10,"isHidden":false,"tableData":[{"rows":[[301,"Aditya"],[302,"Neha"]],"columns":[{"name":"customer_id","type":"INT","isPrimaryKey":true},{"name":"name","type":"VARCHAR"}],"tableName":"Customers"},{"rows":[[1,301,5000,"Pending"],[2,302,4000,"Pending"]],"columns":[{"name":"order_id","type":"INT","isPrimaryKey":true},{"name":"customer_id","type":"INT"},{"name":"amount","type":"INT"},{"name":"status","type":"VARCHAR"}],"tableName":"Orders"}],"description":"All pending orders","expectedOutput":[],"expectedColumns":["name","total_spent"]},{"id":5,"name":"Hidden Test 1","points":10,"isHidden":true,"tableData":[{"rows":[[401,"Aarav"],[402,"Ishita"]],"columns":[{"name":"customer_id","type":"INT","isPrimaryKey":true},{"name":"name","type":"VARCHAR"}],"tableName":"Customers"},{"rows":[[1,401,4000,"Pending"],[2,401,2500,"Completed"],[3,402,3500,"Completed"]],"columns":[{"name":"order_id","type":"INT","isPrimaryKey":true},{"name":"customer_id","type":"INT"},{"name":"amount","type":"INT"},{"name":"status","type":"VARCHAR"}],"tableName":"Orders"}],"description":"Ignore pending orders","expectedOutput":[["Ishita",3500]],"expectedColumns":["name","total_spent"]},{"id":6,"name":"Hidden Test 2","points":10,"isHidden":true,"tableData":[{"rows":[[501,"Neha"],[502,"Rohan"]],"columns":[{"name":"customer_id","type":"INT","isPrimaryKey":true},{"name":"name","type":"VARCHAR"}],"tableName":"Customers"},{"rows":[[1,501,1200,"Completed"],[2,501,800,"Completed"],[3,502,1500,"Completed"]],"columns":[{"name":"order_id","type":"INT","isPrimaryKey":true},{"name":"customer_id","type":"INT"},{"name":"amount","type":"INT"},{"name":"status","type":"VARCHAR"}],"tableName":"Orders"}],"description":"All completed orders below threshold","expectedOutput":[],"expectedColumns":["name","total_spent"]},{"id":7,"name":"Hidden Test 3","points":10,"isHidden":true,"tableData":[{"rows":[[601,"Aditya"],[602,"Ananya"]],"columns":[{"name":"customer_id","type":"INT","isPrimaryKey":true},{"name":"name","type":"VARCHAR"}],"tableName":"Customers"},{"rows":[[1,601,5000,"Completed"],[2,601,4000,"Completed"],[3,602,2000,"Pending"]],"columns":[{"name":"order_id","type":"INT","isPrimaryKey":true},{"name":"customer_id","type":"INT"},{"name":"amount","type":"INT"},{"name":"status","type":"VARCHAR"}],"tableName":"Orders"}],"description":"Large completed amounts","expectedOutput":[["Aditya",9000]],"expectedColumns":["name","total_spent"]},{"id":8,"name":"Hidden Test 4","points":10,"isHidden":true,"tableData":[{"rows":[[701,"Kiran"],[702,"Sneha"]],"columns":[{"name":"customer_id","type":"INT","isPrimaryKey":true},{"name":"name","type":"VARCHAR"}],"tableName":"Customers"},{"rows":[[1,701,5000,"Pending"],[2,702,4000,"Pending"]],"columns":[{"name":"order_id","type":"INT","isPrimaryKey":true},{"name":"customer_id","type":"INT"},{"name":"amount","type":"INT"},{"name":"status","type":"VARCHAR"}],"tableName":"Orders"}],"description":"No completed orders at all","expectedOutput":[],"expectedColumns":["name","total_spent"]}]', '["select","from","join","where","group","having"]', 40, 180, 'SELECT c.name, SUM(o.amount) AS total_spent FROM Customers c JOIN Orders o ON c.customer_id = o.customer_id WHERE o.status = ''Completed'' GROUP BY c.name HAVING SUM(o.amount) > 3000;', true, '2026-03-27 09:39:08.352718+00', '2026-03-27 15:19:06.165+00'), (6, 'medium', 'Multiple Logins Per Day', 'Find users who logged in more than once on the same day. Return user_id and login_date.', 'A system tracks user logins with timestamps.\nEach user may log in multiple times on the same or different days.\nThe company wants to identify users who have logged in more than once on the same day.\n\nTask: Return user_id and login_date.', 'CREATE TABLE Logins (user_id INT, login_time TIMESTAMP);', '[{"rows":[[101,"2024-03-01 10:00:00"],[101,"2024-03-01 15:00:00"],[102,"2024-03-01 09:00:00"],[102,"2024-03-02 11:00:00"]],"columns":[{"name":"user_id","type":"INT","isForeignKey":false,"isPrimaryKey":false},{"name":"login_time","type":"TIMESTAMP","isForeignKey":false,"isPrimaryKey":false}],"tableName":"Logins"}]', '[{"id":1,"name":"Sample Test","points":10,"isHidden":false,"tableData":[{"rows":[[101,"2024-03-01 10:00:00"],[101,"2024-03-01 15:00:00"],[102,"2024-03-01 09:00:00"],[102,"2024-03-02 11:00:00"]],"columns":[{"name":"user_id","type":"INT"},{"name":"login_time","type":"TIMESTAMP"}],"tableName":"Logins"}],"description":"Basic case with one user logging in twice","expectedOutput":[["101","2024-03-01"]],"expectedColumns":["user_id","login_date"]},{"id":2,"name":"Test Case 2","points":10,"isHidden":false,"tableData":[{"rows":[[201,"2024-04-10 08:00:00"],[201,"2024-04-10 09:00:00"],[201,"2024-04-10 10:00:00"],[202,"2024-04-11 12:00:00"]],"columns":[{"name":"user_id","type":"INT"},{"name":"lo