alue sales","expectedOutput":[["2024-03-01",1200,800],["2024-03-02",1500,300],["2024-03-03",0,900]],"expectedColumns":["sale_date","high_sales","low_sales"]},{"id":2,"name":"Test Case 2","points":10,"isHidden":false,"tableData":[{"rows":[[101,2500,"2024-04-05"],[102,1800,"2024-04-05"],[103,4500,"2024-04-06"]],"columns":[{"name":"sale_id","type":"INT","isPrimaryKey":true},{"name":"amount","type":"INT"},{"name":"sale_date","type":"DATE"}],"tableName":"sales"}],"description":"Only high value sales","expectedOutput":[["2024-04-05",4300,0],["2024-04-06",4500,0]],"expectedColumns":["sale_date","high_sales","low_sales"]},{"id":3,"name":"Test Case 3","points":10,"isHidden":false,"tableData":[{"rows":[[201,450,"2024-05-10"],[202,750,"2024-05-10"],[203,200,"2024-05-11"]],"columns":[{"name":"sale_id","type":"INT","isPrimaryKey":true},{"name":"amount","type":"INT"},{"name":"sale_date","type":"DATE"}],"tableName":"sales"}],"description":"Only low value sales","expectedOutput":[["2024-05-10",0,1200],["2024-05-11",0,200]],"expectedColumns":["sale_date","high_sales","low_sales"]},{"id":4,"name":"Test Case 4","points":10,"isHidden":false,"tableData":[{"rows":[[301,2000,"2024-06-15"],[302,500,"2024-06-17"]],"columns":[{"name":"sale_id","type":"INT","isPrimaryKey":true},{"name":"amount","type":"INT"},{"name":"sale_date","type":"DATE"}],"tableName":"sales"}],"description":"No sales on some days","expectedOutput":[["2024-06-15",2000,0],["2024-06-17",0,500]],"expectedColumns":["sale_date","high_sales","low_sales"]},{"id":5,"name":"Hidden Test 1","points":10,"isHidden":true,"tableData":[{"rows":[[1,5000,"2024-07-01"],[2,900,"2024-07-01"],[3,1500,"2024-07-02"],[4,1200,"2024-07-02"],[5,800,"2024-07-03"]],"columns":[{"name":"sale_id","type":"INT","isPrimaryKey":true},{"name":"amount","type":"INT"},{"name":"sale_date","type":"DATE"}],"tableName":"sales"}],"description":"Large amounts and multiple days","expectedOutput":[["2024-07-01",5000,900],["2024-07-02",2700,0],["2024-07-03",0,800]],"expectedColumns":["sale_date","high_sales","low_sales"]},{"id":6,"name":"Hidden Test 2","points":10,"isHidden":true,"tableData":[{"rows":[[1,0,"2024-08-01"],[2,-100,"2024-08-01"],[3,500,"2024-08-02"]],"columns":[{"name":"sale_id","type":"INT","isPrimaryKey":true},{"name":"amount","type":"INT"},{"name":"sale_date","type":"DATE"}],"tableName":"sales"}],"description":"All zero or negative amounts","expectedOutput":[["2024-08-01",0,0],["2024-08-02",0,500]],"expectedColumns":["sale_date","high_sales","low_sales"]},{"id":7,"name":"Hidden Test 3","points":10,"isHidden":true,"tableData":[{"rows":[[1,5000,"2024-09-01"],[2,6000,"2024-09-01"],[3,400,"2024-09-02"]],"columns":[{"name":"sale_id","type":"INT","isPrimaryKey":true},{"name":"amount","type":"INT"},{"name":"sale_date","type":"DATE"}],"tableName":"sales"}],"description":"High value only on one day","expectedOutput":[["2024-09-01",11000,0],["2024-09-02",0,400]],"expectedColumns":["sale_date","high_sales","low_sales"]},{"id":8,"name":"Hidden Test 4","points":10,"isHidden":true,"tableData":[{"rows":[],"columns":[{"name":"sale_id","type":"INT","isPrimaryKey":true},{"name":"amount","type":"INT"},{"name":"sale_date","type":"DATE"}],"tableName":"sales"}],"description":"Empty sales table","expectedOutput":[],"expectedColumns":["sale_date","high_sales","low_sales"]}]', '["select","from","group","order"]', 40, 180, 'SELECT sale_date, SUM(CASE WHEN amount >= 1000 THEN amount ELSE 0 END) AS high_sales, SUM(CASE WHEN amount < 1000 THEN amount ELSE 0 END) AS low_sales FROM sales GROUP BY sale_date ORDER BY sale_date;', true, '2026-03-27 09:39:50.111018+00', '2026-03-27 15:19:26.495+00'), (8, 'hard', 'Same Salary but Not Highest', 'Find employees who share the same salary with at least one other employee, but their salary is NOT the highest in the company.', 'A company tracks employee salaries.\nSome employees share the same salary.\nThe company wants employees who:\n• Share the same salary with at least one other employee, AND\n• Their s