:[{"rows":[[301,50000],[302,50000],[303,50000]],"columns":[{"name":"emp_id","type":"INT","isForeignKey":false,"isPrimaryKey":true},{"name":"salary","type":"INT","isForeignKey":false,"isPrimaryKey":false}],"tableName":"Employees"}],"description":"All employees have same salary","expectedOutput":[],"expectedColumns":[]},{"id":6,"name":"Hidden Test 2","points":50,"isHidden":true,"tableData":[{"rows":[[401,75000],[402,75000],[403,60000]],"columns":[{"name":"emp_id","type":"INT","isForeignKey":false,"isPrimaryKey":true},{"name":"salary","type":"INT","isForeignKey":false,"isPrimaryKey":false}],"tableName":"Employees"}],"description":"Duplicate salary is the maximum","expectedOutput":[],"expectedColumns":[]},{"id":7,"name":"Hidden Test 3","points":50,"isHidden":true,"tableData":[{"rows":[[501,40000],[502,40000],[503,55000],[504,55000],[505,70000]],"columns":[{"name":"emp_id","type":"INT","isForeignKey":false,"isPrimaryKey":true},{"name":"salary","type":"INT","isForeignKey":false,"isPrimaryKey":false}],"tableName":"Employees"}],"description":"Multiple groups - only non-max group","expectedOutput":[],"expectedColumns":[]},{"id":8,"name":"Hidden Test 4","points":50,"isHidden":true,"tableData":[{"rows":[[601,80000]],"columns":[{"name":"emp_id","type":"INT","isForeignKey":false,"isPrimaryKey":true},{"name":"salary","type":"INT","isForeignKey":false,"isPrimaryKey":false}],"tableName":"Employees"}],"description":"Only one employee","expectedOutput":[],"expectedColumns":[]}]', '["select","from","join","where","from"]', 350, 180, 'SELECT DISTINCT e1.emp_id FROM Employees e1 JOIN Employees e2 ON e1.salary = e2.salary AND e1.emp_id != e2.emp_id WHERE e1.salary < (SELECT MAX(salary) FROM Employees);', true, '2026-03-27 09:40:16.125556+00', '2026-03-27 15:19:35.423+00'), (9, 'hard', 'Premium Customers Investment Analysis', 'Find the total investment in 2023 for users who have duplicate inv_2022 value AND belong to a unique city.', 'Write a query to find the total investment in 2023 (inv_2023) for users who satisfy BOTH conditions:\n1. Their inv_2022 value appears more than once (at least one other user has same inv_2022)\n2. They belong to a city that is unique (no other user from the same city)\n\nReturn a single value: total_investment_2023 (rounded to 2 decimal places).', 'CREATE TABLE Investments (user_id INT PRIMARY KEY, inv_2022 FLOAT, inv_2023 FLOAT, city VARCHAR, branch_id INT);', '[{"rows":[[1,1000,2000,"Chennai",1],[2,1000,3000,"Mumbai",2],[3,2000,4000,"Delhi",1],[4,3000,5000,"Delhi",2]],"columns":[{"name":"user_id","type":"INT","isForeignKey":false,"isPrimaryKey":true},{"name":"inv_2022","type":"FLOAT","isForeignKey":false,"isPrimaryKey":false},{"name":"inv_2023","type":"FLOAT","isForeignKey":false,"isPrimaryKey":false},{"name":"city","type":"VARCHAR","isForeignKey":false,"isPrimaryKey":false},{"name":"branch_id","type":"INT","isForeignKey":false,"isPrimaryKey":false}],"tableName":"Investments"}]', '[{"id":1,"name":"Sample Test","points":30,"isHidden":false,"tableData":[{"rows":[[1,1000,2000,"Chennai",1],[2,1000,3000,"Mumbai",2],[3,2000,4000,"Delhi",1],[4,3000,5000,"Delhi",2]],"columns":[{"name":"user_id","type":"INT","isForeignKey":false,"isPrimaryKey":true},{"name":"inv_2022","type":"FLOAT","isForeignKey":false,"isPrimaryKey":false},{"name":"inv_2023","type":"FLOAT","isForeignKey":false,"isPrimaryKey":false},{"name":"city","type":"VARCHAR","isForeignKey":false,"isPrimaryKey":false},{"name":"branch_id","type":"INT","isForeignKey":false,"isPrimaryKey":false}],"tableName":"Investments"}],"description":"Base example with duplicate inv_2022 and unique cities","expectedOutput":[],"expectedColumns":[]},{"id":2,"name":"Test Case 2","points":30,"isHidden":false,"tableData":[{"rows":[[101,5000,6000,"Bangalore",5],[102,7000,8000,"Hyderabad",6],[103,9000,10000,"Pune",7]],"columns":[{"name":"user_id","type":"INT","isForeignKey":false,"isPrimaryKey":true},{"name":"inv_2022","type":"FLOAT","isForeignKey":false,"isPrimaryKey":false},{"name":"inv_202